import os
import django
from django.conf import settings
from django.db import models
from django.db.models import Count

# Configure Django settings
if not settings.configured:
    settings.configure(
        DATABASES={
            'default': {
                'ENGINE': 'django.db.backends.sqlite3',
                'NAME': ':memory:',
            }
        },
        INSTALLED_APPS=[
            'repro',
        ],
    )
    django.setup()

# Create a simple app for reproduction
from django.apps import AppConfig
class ReproConfig(AppConfig):
    name = 'repro'

class MyModel(models.Model):
    name = models.CharField(max_length=100)
    value = models.IntegerField()

    class Meta:
        app_label = 'repro'
        ordering = ['name']

# Create the table in the database
with django.db.connection.schema_editor() as schema_editor:
    schema_editor.create_model(MyModel)

# Insert some data
MyModel.objects.create(name='A', value=10)
MyModel.objects.create(name='B', value=10)
MyModel.objects.create(name='C', value=20)

# We want to group by 'value' only.
qs = MyModel.objects.values('value').annotate(count=Count('id'))
print("\nQuerySet results:")
for item in qs:
    print(item)

# Expected output:
# {'value': 10, 'count': 2}
# {'value': 20, 'count': 1}

# If Meta.ordering = ['name'] is included in GROUP BY, it will be:
# {'value': 10, 'count': 1}
# {'value': 10, 'count': 1}
# {'value': 20, 'count': 1}

# Let's check the generated SQL.
print("\nGenerated SQL:")
print(qs.query)
